int gdImageColorClosestAlpha (gdImagePtr im, int r, int g, int b, int a)
{
  int i;
  long rd, gd, bd, ad;
  int ct = (-1);
  int first = 1;
  long mindist = 0;

  if (im->trueColor) {
    return gdTrueColorAlpha(r, g, b, a);
  }
  for (i = 0; i < im->colorsTotal; i++) {
    long dist;
    if (im->open[i]) {
      continue;
    }
    rd = im->red[i] - r;
    gd = im->green[i] - g;
    bd = im->blue[i] - b;
